import json, gzip, base64, pathlib, sys

ROOT = pathlib.Path('data/shows/rex-fleet-s1')


def load_issue(n):
    if n == 2:
        return json.loads((ROOT/'scenes_e02.json').read_text())
    p = ROOT/'encoded'/f'scenes_e{n:02d}.json.gzb64'
    raw = base64.b64decode(''.join(p.read_text().split()))
    return json.loads(gzip.decompress(raw).decode('utf-8'))


def save_issue(n, data):
    if n == 2:
        (ROOT/'scenes_e02.json').write_text(json.dumps(data, ensure_ascii=False, separators=(',', ':'))+'\n')
        return
    p = ROOT/'encoded'/f'scenes_e{n:02d}.json.gzb64'
    payload = json.dumps(data, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    p.write_text(base64.b64encode(gzip.compress(payload, mtime=0)).decode('ascii')+'\n')

rew = {i: load_issue(i) for i in range(2,13)}
touched=set()

def scene_map(issue):
    return {s['id']: s for s in rew[issue]}

def D(issue, sid, items):
    touched.add((issue,sid))
    s = scene_map(issue)[sid]
    s['dialogueInline'] = []
    for item in items:
        d = {'handle': item[0], 'speaker': item[1], 'text': item[2]}
        if len(item) > 3 and item[3]: d['subtext'] = item[3]
        s['dialogueInline'].append(d)

def no_dialogue(issue, sid):
    touched.add((issue,sid))
    scene_map(issue)[sid].pop('dialogueInline', None)

def set_direction(issue, sid, text):
    touched.add((issue,sid))
    scene_map(issue)[sid]['directionInline'] = [text]

def set_panelplan(issue, sid, panels):
    touched.add((issue,sid))
    scene_map(issue)[sid]['panelPlan'] = panels

