D(2,'RF_S1E02_A05',[('@starsplit.brent.wallace','Wallace',"You're really going to let the Fleet set the route?"),('@starsplit.halev','Halev',"For one night, I'm going to let whoever gets the food here set the route."),('@starsplit.brent.wallace','Wallace',"That's not reassuring."),('@starsplit.halev','Halev',"Didn't say it was.")])
