D(2,'RF_S1E02_A06',[('@starsplit.cael.dominion','Dominion',"Open one lane and they'll use it to measure the wall."),('@starsplit.ella.venn','Venn','Then let them measure it.'),('@starsplit.admiral.janet.keating','Keating','And when the first freighter brings rifles?'),('@starsplit.admiral.colin.rhyne','Rhyne','Search it.'),('@starsplit.cael.dominion','Dominion','That simple?'),('@starsplit.admiral.colin.rhyne','Rhyne','No. Still our job.')])
