no_dialogue(2,'RF_S1E02_A12'); set_direction(2,'RF_S1E02_A12',"Ashfang breaks Abby's assigned vector and strafes the storage spine. Heater cells and thermal blankets burst into bright sheets of burning debris while dark civilian habitat rings sit beyond them. Hold on Billie's face only after the shot: she expected spectacle; the image outside is uglier and more wasteful than the cheer she wanted. No line tells the reader what to feel.")
D(2,'RF_S1E02_A13',[('@starsplit.tactical','Tactical',"Ashfang's lining up on the clinic ship."),('@starsplit.ella.venn','Venn','Put us between them.'),('@starsplit.tactical','Tactical',"That's inside her range."),('@starsplit.ella.venn','Venn','I know.')]); set_direction(2,'RF_S1E02_A13',"The clinic freighter fills the center of the tactical display with Ashfang's firing cone closing over it. Venn orders Thunderbreak across the cone. Exterior beat: the heavy cruiser shoulders a drifting structural beam aside and takes the exposed position itself. Sparks rake the armor when Ashfang fires past.")
D(2,'RF_S1E02_A14',[('@starsplit.naomi.sol','Naomi',"Blue Two, you're drifting. Get back on me."),('@starsplit.naomi.sol','Naomi','Clinic pods stay inside the line. Come on—there you go.')]); set_direction(2,'RF_S1E02_A14',"Naomi's escort line wobbles under pressure. One pilot slides too far out; she talks that ship back into place while her own hands shake on the controls. The medpods settle inside the protective geometry. Her fear is visible, but the dialogue is only about the immediate flying problem.")
D(2,'RF_S1E02_A15',[('@starsplit.billie.rusk','Billie','You tucked a freighter in my blind side.'),('@starsplit.tessa.banks','Tess','You had plenty to look at.'),('@starsplit.billie.rusk','Billie',"Next time I won't miss."),('@starsplit.tessa.banks','Tess','Then look first.')]); set_direction(2,'RF_S1E02_A15',"Ashfang and Gravefire cross on opposite withdrawal vectors. Billie finally spots the rescued freighter tucked into Gravefire's debris shadow. The two captains see each other through magnified canopy feeds for the exchange; neither ship slows down.")
D(2,'RF_S1E02_A16',[('@starsplit.halev','Halev',"I don't think we can get by with any less than eight ships."),('@starsplit.jex.marrin','Jex',"That's six more than you have now. I can give you four additional."),('@starsplit.halev','Halev','I said I need six from you.'),('@starsplit.jex.marrin','Jex','Maybe you need another smuggler.'),('@starsplit.jex.marrin','Jex','Do you know any other smugglers?'),('@starsplit.halev','Halev','Okay. Five.'),('@starsplit.jex.marrin','Jex',"Fine. Five. I'm either getting weak or lazy. Dammit. Five.")])
